<?php declare(strict_types=1); $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$v=$values??[]; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Reserve a vehicle | Triple R Gensan</title><link rel="stylesheet" href="/assets/css/app.css"><script src="/assets/js/rentals.js" defer></script></head><body><header class="topbar"><a class="brand" href="/staff">Triple R Gensan</a><nav class="staff-actions"><a href="/rentals">Agreements</a><a href="/customers">Customers</a><a href="/fleet/vehicles">Fleet</a></nav></header><main class="page-shell"><section class="page-heading"><div><p class="eyebrow">Rental management</p><h1>Reserve a vehicle</h1><p>Self-drive reservations are available. Chauffeur rentals will be enabled with M6 driver assignment.</p></div></section><?php if($error):?><p class="alert" role="alert"><?= $e($error) ?></p><?php endif;?><form class="panel form-grid" method="post" action="/rentals/reserve"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="rental_type" value="self_drive"><label>Customer<select name="customer_id" required><option value="">Choose eligible customer</option><?php foreach($customers as $c):?><option value="<?= (int)$c['customer_id'] ?>"<?= (string)($v['customer_id']??'')===(string)$c['customer_id']?' selected':'' ?>><?= $e($c['full_name']) ?><?= $c['company_name']?' — '.$e($c['company_name']):'' ?></option><?php endforeach;?></select></label><label>Vehicle<select name="vehicle_id" required><option value="">Choose available vehicle</option><?php foreach($vehicles as $car):?><option value="<?= (int)$car['vehicle_id'] ?>" data-rate="<?= $e($car['daily_rate']) ?>"<?= (string)($v['vehicle_id']??'')===(string)$car['vehicle_id']?' selected':'' ?>><?= $e($car['plate_number'].' — '.$car['model_year'].' '.$car['make'].' '.$car['model'].' — ₱'.$car['daily_rate'].'/day') ?></option><?php endforeach;?></select></label><label>Pickup date (Manila)<input type="date" name="start_date" required value="<?= $e($v['start_date']??'') ?>"></label><label>Return date (Manila)<input type="date" name="end_date" required value="<?= $e($v['end_date']??'') ?>"></label><label>Scheduled pickup time (Manila)<input type="datetime-local" name="scheduled_pickup_at" required value="<?= $e($v['scheduled_pickup_at']??'') ?>"></label><label>Scheduled return time (Manila)<input type="datetime-local" name="scheduled_return_at" required value="<?= $e($v['scheduled_return_at']??'') ?>"></label><label>Security deposit (₱)<input type="number" name="deposit_amount" min="0" max="99999999.99" step="0.01" value="<?= $e($v['deposit_amount']??'0.00') ?>" required></label><p class="muted">Same-day rentals bill as one day. A 60-minute reservation hold begins when this reservation is saved.</p><button type="submit">Create reservation</button></form></main></body></html>
